<?php require 'inc.php';$mon=$_GET['m']??date('Y-m');$rows=calc($mon);
if(isset($_GET['csv'])){header('Content-Type: text/csv');header('Content-Disposition: attachment; filename=report-'.$mon.'.csv');$o=fopen('php://output','w');fputcsv($o,['Farmer','Deliveries','Litres accepted','Litres rejected','Gross','Deductions','Net']);foreach($rows as $r)fputcsv($o,[$r['full_name'],$r['deliveries'],$r['litres'],$r['rejected'],$r['gross'],$r['ded'],$r['net']]);exit;}
start('Monthly report');$T=['deliveries'=>0,'litres'=>0,'rejected'=>0,'gross'=>0,'ded'=>0,'net'=>0];?>
<div class="card"><form class="row" method="get"><div><label>Month</label><input type="month" name="m" value="<?=e($mon)?>"></div><button>Show</button><a class="btn alt" href="?m=<?=e($mon)?>&csv=1">Download CSV</a><a class="btn alt" href="#" onclick="window.print();return false">Print</a></form></div>
<div class="card wrap"><table><tr><th>Farmer</th><th>Deliveries</th><th>Litres accepted</th><th>Litres rejected</th><th>Gross</th><th>Deductions</th><th>Net pay</th></tr><?php foreach($rows as $r){foreach($T as $k=>$_)$T[$k]+=$r[$k];echo '<tr><td>'.e($r['full_name']).'</td><td>'.$r['deliveries'].'</td><td>'.$r['litres'].'</td><td>'.$r['rejected'].'</td><td>'.n($r['gross']).'</td><td>'.n($r['ded']).'</td><td>'.n($r['net']).'</td></tr>';}
echo '<tr><th>Total</th><th>'.$T['deliveries'].'</th><th>'.$T['litres'].'</th><th>'.$T['rejected'].'</th><th>'.n($T['gross']).'</th><th>'.n($T['ded']).'</th><th>'.n($T['net']).'</th></tr>';?></table></div>
<p>Milk sales income this month: <b>UGX <?=n(q("SELECT COALESCE(SUM(litres*price_per_litre),0) FROM milk_sale WHERE DATE_FORMAT(sale_date,'%Y-%m')=?",[$mon])->fetchColumn())?></b></p><?php done();
